/* Revisa+ — PWA offline-first. Sem bibliotecas externas e sem envio de dados. */
(() => {
  'use strict';
  const KEY = 'revisaplus_data_v1';
  const DAY = 86400000;
  const H = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon = (name, cls='') => `<svg class="ic ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
  const uid = () => (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : 'r'+Date.now().toString(36)+Math.random().toString(36).slice(2,11);
  const localDay = (value = new Date()) => { const d = value instanceof Date ? value : new Date(value); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const parseDay = s => {const [y,m,d]=String(s).split('-').map(Number);return new Date(y||2026,(m||1)-1,d||1,12,0,0);};
  const addDays = (day, n) => { const d = parseDay(day); d.setDate(d.getDate()+n); return localDay(d); };
  const diffDays = (a,b) => Math.round((parseDay(a)-parseDay(b))/DAY);
  const fmt = d => {if (!d) return '—';const parts=String(d).split('-');return `${parts[2]}/${parts[1]}/${parts[0]}`;};
  const today = () => localDay();
  const fmtLong = d => new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',year:'numeric'}).format(parseDay(d));
  const fmtMonth = d => new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(parseDay(d));
  const ucfirst = s => s.charAt(0).toUpperCase()+s.slice(1);
  const total = (arr, fn) => arr.reduce((n,x)=>n+fn(x),0);
  const clamp = (n,min,max) => Math.max(min,Math.min(max,n));
  const randColors = ['#7d89f9','#4fd1ad','#edb66a','#60bce5','#d993ef','#f37990','#7ebd82','#a58aff'];
  const defaults = () => ({
    version:1,createdAt:new Date().toISOString(),
    settings:{theme:'dark',dailyCap:40,defaultReviewMinutes:12,intervals:[1,3,7,15,30,60,120,240],notifications:false},
    subjects:[['Matemática','#7d89f9'],['Português','#4fd1ad'],['Física','#edb66a'],['Química','#60bce5'],['História','#d993ef'],['Geografia','#f37990'],['Inglês','#7ebd82']].map(([name,color])=>({id:uid(),name,color,exam:'',createdAt:new Date().toISOString()})),
    topics:[],reviews:[],studySessions:[],flashcards:[],flashReviews:[],questions:[],quizAttempts:[],errors:[]
  });
  const LISTS = ['subjects','topics','reviews','studySessions','flashcards','flashReviews','questions','quizAttempts','errors'];
  function load() {try {const raw=localStorage.getItem(KEY); if(!raw) return defaults(); const d=JSON.parse(raw);if(!d||!Array.isArray(d.topics))throw Error('formato');const empty=defaults();LISTS.forEach(k=>d[k]=Array.isArray(d[k])?d[k]:empty[k]);d.settings={...empty.settings,...d.settings};return d;}catch(e){console.warn('Falha ao ler dados:',e);return defaults();}}
  let db=load();
  let ui={page:'home',menu:false,reviewFilter:'pending',librarySubject:'all',librarySearch:'',flashSubject:'all',questionSubject:'all',errorFilter:'open',calendarMonth:today().slice(0,7)+'-01',calendarDay:today(),statsRange:30,activeFlash:null,quiz:null,reportReady:false};
  let currentReview=null; let deferredInstall=null; let toastTimeout=null; let noticeSeen='';
  const sById = id => db.subjects.find(x=>x.id===id);
  const tById = id => db.topics.find(x=>x.id===id);
  const subjectName = id => sById(id)?.name || 'Disciplina excluída';
  const topicName = id => tById(id)?.title || 'Conteúdo excluído';
  const subjectColor = id => sById(id)?.color || '#8490ff';
  const activeTopics = () => db.topics.filter(t=>!t.paused);
  const due = () => activeTopics().filter(t=>t.dueDate && t.dueDate<=today());
  const overdue = () => due().filter(t=>t.dueDate<today());
  const dueSort = (a,b) => (a.dueDate.localeCompare(b.dueDate)) || ((b.priority||2)-(a.priority||2)) || a.title.localeCompare(b.title);
  const countsFor = id => db.topics.filter(t=>t.subjectId===id).length;
  const last30 = (arr, key='at', days=30) => arr.filter(x=>localDay(x[key])>=addDays(today(),-(days-1)));
  const grades = {again:['Não lembrei','red'],hard:['Com dificuldade','yellow'],good:['Lembrei bem','blue'],easy:['Muito fácil','green']};
  const getGrade = grade => grades[grade]||['Revisão','grey'];
  const reviewMinutes = t => Number(t.reviewMinutes || db.settings.defaultReviewMinutes);
  const currentStreak = () => { const days=new Set([...db.studySessions.map(s=>s.date),...db.reviews.map(r=>localDay(r.at)),...db.flashReviews.map(r=>localDay(r.at))]);let day=days.has(today())?today():addDays(today(),-1),streak=0;while(streak<10000&&days.has(day)){streak++;day=addDays(day,-1);}return streak; };
  const minutes = n => n>=60 ? `${Math.floor(n/60)}h${n%60?` ${n%60}min`:''}` : `${n}min`;
  const reviewState = t => t.dueDate<today()?'overdue':t.dueDate===today()?'today':'upcoming';
  const subjOpts = (value, withAll=false) => `${withAll?'<option value="all">Todas as disciplinas</option>':''}${db.subjects.map(s=>`<option value="${s.id}" ${s.id===value?'selected':''}>${H(s.name)}</option>`).join('')}`;
  const topicOpts = (value, withAll=false) => `${withAll?'<option value="all">Todos os conteúdos</option>':''}${db.topics.map(t=>`<option value="${t.id}" ${t.id===value?'selected':''}>${H(subjectName(t.subjectId))} · ${H(t.title)}</option>`).join('')}`;
  const opt = (v,sel,label=v) => `<option value="${H(v)}" ${String(v)===String(sel)?'selected':''}>${H(label)}</option>`;
  const badge = (label,color='grey') => `<span class="pill ${color}">${H(label)}</span>`;
  const num = v => new Intl.NumberFormat('pt-BR').format(v);
  function save() {try {localStorage.setItem(KEY,JSON.stringify(db));return true;}catch(e){toast('Não foi possível salvar. Exporte um backup e libere espaço no navegador.');return false;}}
  function toast(message){const root=document.querySelector('#toast-root');root.innerHTML=`<div class="toast-wrap"><div class="toast">${H(message)}</div></div>`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>root.innerHTML='',3500);}
  const button = (label,action,data='',cls='') => `<button type="button" class="btn ${cls}" data-action="${action}" ${data}>${label}</button>`;
  const navs = [['home','home','Hoje'],['calendar','calendar','Agenda'],['library','book','Biblioteca'],['flash','card','Flashcards'],['questions','target','Questões'],['errors','alert','Erros'],['stats','chart','Estatísticas'],['settings','settings','Ajustes']];
  function go(page){ui.page=page;ui.menu=false;ui.activeFlash=null;if(page!=='questions')ui.quiz=null;window.scrollTo(0,0);render();}
  function render(){
    document.body.classList.toggle('light',db.settings.theme==='light');
    document.querySelector('meta[name="theme-color"]').content = db.settings.theme==='light'?'#f3f5fb':'#10172b';
    const names={home:'Visão geral',calendar:'Agenda',library:'Biblioteca',flash:'Flashcards',questions:'Questões',errors:'Caderno de erros',stats:'Estatísticas',settings:'Configurações'};
    const c=due().length;
    document.getElementById('app').innerHTML=`<div class="app-shell">
      <div class="overlay-side ${ui.menu?'show':''}" data-action="menu-close"></div>
      <aside class="sidebar ${ui.menu?'open':''}">
       <div class="brand"><div class="brand-mark">${icon('check','lg')}</div><div><div class="brand-name">Revisa<span class="accent">+</span></div><div class="brand-caption">ESTUDE. REVISE. DOMINE.</div></div></div>
       <div class="side-label">PRINCIPAL</div><div class="nav">
       ${navs.map(([id,ic,label],i)=>`${i===5?'</div><div class="side-label">ACOMPANHAMENTO</div><div class="nav">':''}<button class="nav-btn ${ui.page===id?'active':''}" data-action="go" data-page="${id}">${icon(ic)}<span>${label}</span>${id==='calendar'&&c?`<span class="nav-count">${c>99?'99+':c}</span>`:''}</button>`).join('')}
       </div><div class="sidebar-bottom"><div class="side-mini"><div class="flex strong small">${icon('flame')} ${currentStreak()} dia(s) de sequência</div><div class="small muted" style="margin-top:7px">Dados salvos neste dispositivo. Faça backups em Ajustes.</div></div></div>
      </aside>
      <div class="main-wrap"><header class="topbar">
        <button class="btn plain mobile-menu-btn" aria-label="Abrir menu" data-action="menu-toggle">${icon('menu','lg')}</button>
        <div class="topbar-title">${names[ui.page]}</div><div class="topbar-date">${ucfirst(fmtLong(today()))}</div>
        <button class="btn square ghost" aria-label="Alternar tema" title="Alternar tema" data-action="theme">${icon(db.settings.theme==='dark'?'sun':'moon')}</button>
        <button class="btn square ghost" aria-label="Ver revisões pendentes" title="Revisões pendentes" data-action="go" data-page="calendar">${icon('bell')}</button>
        <button class="btn primary" data-action="topic-add">${icon('plus')}<span>Novo conteúdo</span></button>
       </header><main class="content" id="main-content">${pageHtml()}</main></div>
      <nav class="mobile-bar" aria-label="Navegação inferior">
      ${[['home','home','Hoje'],['calendar','calendar','Agenda'],['library','book','Conteúdos'],['flash','card','Revisar'],['more','menu','Mais']].map(([id,ic,label])=>`<button class="mobile-tab ${ui.page===id?'active':''}" data-action="${id==='more'?'menu-toggle':'go'}" ${id!=='more'?`data-page="${id}"`:''}>${icon(ic)}<span>${label}</span></button>`).join('')}
      </nav></div>`;
  }
  function pageHtml(){switch(ui.page){case 'calendar':return calendarPage();case 'library':return libraryPage();case 'flash':return flashPage();case 'questions':return questionsPage();case 'errors':return errorsPage();case 'stats':return statsPage();case 'settings':return settingsPage();default:return homePage();}}
  function empty(ic,title,desc,action='',text=''){return `<div class="empty"><div class="empty-icon">${icon(ic,'xl')}</div><h3>${H(title)}</h3><p>${H(desc)}</p>${action?button(text,action,'','primary sm'):''}</div>`;}
  function stat(label,value,sub,ic,color){return `<div class="card stat"><div class="stat-top"><span class="muted small">${label}</span><span class="stat-icon" style="--stat-color:${color}">${icon(ic)}</span></div><div class="stat-value">${value}</div><div class="stat-sub">${sub}</div></div>`;}
  function taskCard(t,showReview=true){const st=reviewState(t),delta=diffDays(today(),t.dueDate);return `<div class="task">
    <div class="task-icon" style="background:${subjectColor(t.subjectId)}22;color:${subjectColor(t.subjectId)}">${icon('book')}</div>
    <div class="task-body"><div class="task-title" title="${H(t.title)}">${H(t.title)}</div><div class="task-sub"><span>${H(subjectName(t.subjectId))}</span><span class="dot"></span><span>${minutes(reviewMinutes(t))}</span><span class="dot"></span>${badge(st==='overdue'?`${delta}d atrasada${delta>1?'s':''}`:st==='today'?'Hoje':fmt(t.dueDate),st==='overdue'?'red':st==='today'?'yellow':'grey')}</div></div>
    ${showReview?button(`${icon('play')} Revisar`,'review-start',`data-id="${t.id}"`,'primary sm'):button(icon('chevron'),'topic-details',`data-id="${t.id}"`,'sm square')}
   </div>`;}
  function weekDays(n=7){return Array.from({length:n},(_,i)=>addDays(today(),i));}
  function homePage(){
   const d=due().sort(dueSort),done=db.reviews.filter(r=>localDay(r.at)===today()).length;
   const doneTopics=new Set(db.reviews.filter(r=>localDay(r.at)===today()).map(r=>r.topicId)).size;
   const studyTime=total(db.studySessions.filter(x=>x.date>=addDays(today(),-6)),x=>Number(x.minutes)||0);
   const weekReviews=last30(db.reviews,'at',30);
   const recall=weekReviews.length?Math.round(100*weekReviews.filter(r=>r.grade==='good'||r.grade==='easy').length/weekReviews.length):0;
   const planned=d.length+done,completion=planned?Math.round(100*done/planned):0;
   const flashDue=db.flashcards.filter(f=>f.dueDate<=today()).length;
   const longest=Array.from({length:7},(_,i)=>{const day=addDays(today(),i),count=activeTopics().filter(t=>t.dueDate===day).length;return{day,count};});
   const maxBar=Math.max(1,...longest.map(x=>x.count));
   const activityBySubject=db.subjects.map(s=>({...s,count:db.topics.filter(t=>t.subjectId===s.id).length})).filter(s=>s.count).sort((a,b)=>b.count-a.count);
   return `<div class="head-row"><div><div class="eyebrow">SEU PAINEL DE ESTUDOS</div><h1 class="h1" style="margin-top:5px">Olá! Vamos manter o ritmo? ${icon('spark','lg')}</h1><p class="section-sub">Cada revisão é mais um passo rumo ao domínio dos conteúdos.</p></div><div class="head-actions">${button(`${icon('plus')} Registrar estudo`,'study-add','','sm')}</div></div>
   <div class="hero"><div><div class="eyebrow" style="color:#b4bafc">REVISÃO INTELIGENTE</div><h2>${d.length?`Você tem ${d.length} ${d.length===1?'revisão':'revisões'} para colocar em dia.`:'Tudo em dia. Que tal aprender algo novo?'}</h2><p>${d.length?`${overdue().length?`${overdue().length} pendente(s) de dias anteriores. `:''}Comece pelo conteúdo mais antigo e mantenha a sequência.`:'Cadastre um conteúdo estudado e receba revisões programadas automaticamente.'}</p><div style="margin-top:19px">${d.length?button(`Iniciar revisão ${icon('arrow')}`,'review-start',`data-id="${d[0].id}"`,'primary'):button(`Adicionar conteúdo ${icon('arrow')}`,'topic-add','','primary')}</div></div><div class="hero-icon">${icon('target','xl')}</div></div>
   <div class="stat-grid">${stat('Revisões pendentes',num(d.length),`${overdue().length} atrasadas`,'calendar','var(--yellow)')}${stat('Revisões hoje',num(done),`${completion}% do total de hoje`,'check','var(--green)')}${stat('Tempo estudado',minutes(studyTime),'nos últimos 7 dias','clock','var(--accent)')}${stat('Boa lembrança',weekReviews.length?`${recall}%`:'—',`${weekReviews.length} revisões em 30 dias`,'target','var(--cyan)')}</div>
   <div class="split"><div class="stack">
     <div class="card card-pad"><div class="card-head"><div><h2 class="h3">Prioridades do dia</h2><p class="section-sub">Conteúdos vencidos e agendados para hoje</p></div>${button(`Ver agenda ${icon('chevron','sm')}`,'go','data-page="calendar"','sm ghost')}</div>
       ${d.length?`<div class="task-list">${d.slice(0,6).map(t=>taskCard(t)).join('')}</div>${d.length>6?`<div style="margin-top:12px">${button(`Mais ${d.length-6} revisões`,'go','data-page="calendar"','sm')}</div>`:''}`:empty('check','Nenhuma revisão pendente','Suas próximas revisões aparecerão aqui.','topic-add','Cadastrar conteúdo')}
     </div>
     <div class="card card-pad"><div class="card-head"><div><h2 class="h3">Acesso rápido</h2><p class="section-sub">Continue sua rotina em poucos cliques</p></div></div><div class="two-grid"><button class="btn" data-action="flash-add">${icon('card')} Novo flashcard</button><button class="btn" data-action="question-add">${icon('target')} Nova questão</button><button class="btn" data-action="error-add">${icon('alert')} Registrar erro</button><button class="btn" data-action="study-add">${icon('clock')} Registrar estudo</button></div></div>
   </div><div class="stack">
    <div class="card card-pad"><div class="card-head"><div><h2 class="h3">Progresso de hoje</h2><p class="section-sub">${done} concluída(s) · ${d.length} pendente(s)</p></div><span class="strong green">${completion}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${completion}%"></div></div><div class="between" style="margin-top:17px"><span class="muted small">Flashcards para revisar</span>${button(`${flashDue} ${icon('chevron','sm')}`,'go','data-page="flash"','sm ghost')}</div><div class="between" style="margin-top:8px"><span class="muted small">Conteúdos cadastrados</span><span class="strong">${db.topics.length}</span></div></div>
    <div class="card card-pad"><div class="card-head"><div><h2 class="h3">Próximos 7 dias</h2><p class="section-sub">Previsão de revisões agendadas</p></div></div><div class="mini-bars">${longest.map(x=>`<div class="bar-group"><span class="tiny muted">${x.count}</span><div class="bar-bg"><div class="bar-fill" style="height:${Math.max(4,100*x.count/maxBar)}%"></div></div><span class="bar-label">${new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(parseDay(x.day)).replace('.','')}</span></div>`).join('')}</div><div class="notice" style="margin-top:20px">${icon('info')}A previsão não inclui conteúdos que ainda serão estudados ou revisões futuras geradas após cada resposta.</div></div>
    <div class="card card-pad"><div class="card-head"><h2 class="h3">Suas disciplinas</h2>${button(icon('plus'),'subject-add','','sm square')}</div>${activityBySubject.length?`<div class="subject-list">${activityBySubject.slice(0,5).map(s=>`<div class="subject-item"><span class="subject-dot" style="background:${s.color}"></span><div class="grow"><div class="between"><span class="small strong">${H(s.name)}</span><span class="tiny muted">${s.count} assunto(s)</span></div><div class="subject-bar"><div style="background:${s.color};width:${100*s.count/Math.max(1,...activityBySubject.map(t=>t.count))}%"></div></div></div></div>`).join('')}</div>`:empty('book','Comece organizando os estudos','Suas matérias aparecerão aqui quando cadastrar conteúdos.')}</div>
   </div></div>`;
  }
  function calendarPage(){
    const month=ui.calendarMonth,first=parseDay(month),start=addDays(month,-((first.getDay()+6)%7));
    const cells=Array.from({length:42},(_,i)=>addDays(start,i));
    const events=activeTopics().filter(t=>t.dueDate===ui.calendarDay || (ui.calendarDay===today()&&t.dueDate<today())).sort(dueSort);
    const reviewed=db.reviews.filter(r=>localDay(r.at)===ui.calendarDay);
    const studies=db.studySessions.filter(s=>s.date===ui.calendarDay);
    return `<div class="head-row"><div><div class="eyebrow">PLANEJAMENTO AUTOMÁTICO</div><h1 class="h1">Sua agenda de revisões</h1><p class="section-sub">Datas geradas pelo método espaçado, com controle manual quando necessário.</p></div><div class="head-actions">${button(`${icon('refresh')} Distribuir atrasos`,'reschedule','','sm')}${button(`${icon('plus')} Novo conteúdo`,'topic-add','','primary sm')}</div></div>
    <div class="calendar-layout"><section class="card calendar-board"><div class="calendar-head"><div><h2 class="h2">${ucfirst(fmtMonth(month))}</h2><div class="small muted">Selecione um dia para visualizar as atividades</div></div><div class="flex">${button(icon('chevron'),'month-prev','','sm square')}${button('Hoje','calendar-today','','sm')}${button(icon('chevron'),'month-next','','sm square')}</div></div><div class="cal-grid">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(x=>`<div class="cal-wd">${x}</div>`).join('')}
    ${cells.map(day=>{const c=activeTopics().filter(t=>t.dueDate===day).length, done=db.reviews.filter(r=>localDay(r.at)===day).length, other=day.slice(0,7)!==month.slice(0,7);return `<button class="cal-day ${other?'other':''} ${day===today()?'today':''} ${day===ui.calendarDay?'selected':''}" data-action="calendar-day" data-day="${day}" aria-label="${fmt(day)}: ${c} revisões"><span class="day-num">${Number(day.slice(8))}</span><div class="cal-dots">${Array.from({length:Math.min(c,3)},()=>`<i class="${day<today()?'overdue':''}"></i>`).join('')}${done?`<i style="background:var(--green)"></i>`:''}</div>${c>3?`<span class="cal-count">+${c-3}</span>`:''}</button>`;}).join('')}</div><div class="legend"><span class="flex"><span class="subject-dot" style="background:var(--accent)"></span> Agendada</span><span class="flex"><span class="subject-dot" style="background:var(--green)"></span> Realizada</span><span class="flex"><span class="subject-dot" style="background:var(--red)"></span> Atrasada</span></div></section>
    <div class="stack"><div class="card card-pad"><div class="card-head"><div><div class="eyebrow">DIA SELECIONADO</div><h2 class="h3" style="margin-top:5px">${fmtLong(ui.calendarDay)}</h2></div>${ui.calendarDay===today()?badge('Hoje','blue'):''}</div><div class="small muted" style="margin-bottom:13px">${events.length} revisões a fazer · ${reviewed.length} realizadas</div>${events.length?`<div class="task-list">${events.map(t=>taskCard(t)).join('')}</div>`:empty('check','Dia livre','Nenhuma revisão agendada para este dia.')}
    ${reviewed.length?`<div class="sep"></div><h3 class="h3" style="margin-bottom:10px">Revisões feitas</h3>${reviewed.slice().reverse().map(r=>`<div class="history-row"><span class="history-icon">${icon('check')}</span><div class="grow"><div class="strong small">${H(topicName(r.topicId))}</div><div class="small muted">${getGrade(r.grade)[0]} · ${Number(r.elapsed)||0} min</div></div></div>`).join('')}`:''}</div>
    <div class="card card-pad"><div class="card-head"><h2 class="h3">Estudos registrados</h2>${button(icon('plus'),'study-add','','sm square')}</div>${studies.length?studies.map(s=>`<div class="mini-stat between"><div class="grow"><div class="small strong">${H(topicName(s.topicId))}</div><div class="tiny muted">${s.minutes} min de ${s.kind==='practice'?'prática':'estudo'}</div></div></div>`).join(''):empty('clock','Nenhum estudo registrado','Anote seus blocos de estudo para visualizar sua consistência.')}</div></div></div>`;
  }
  function libraryPage(){
    const subj=db.subjects.filter(s=>ui.librarySubject==='all'||ui.librarySubject===s.id);
    const filtered=db.topics.filter(t=>(ui.librarySubject==='all'||t.subjectId===ui.librarySubject)&&(!ui.librarySearch||`${t.title} ${subjectName(t.subjectId)} ${t.notes||''}`.toLocaleLowerCase('pt-BR').includes(ui.librarySearch.toLocaleLowerCase('pt-BR')))).sort((a,b)=>a.title.localeCompare(b.title));
    return `<div class="head-row"><div><div class="eyebrow">SEU ACERVO DE CONTEÚDOS</div><h1 class="h1">Biblioteca</h1><p class="section-sub">Organize as disciplinas e acompanhe cada conteúdo do estudo à revisão.</p></div><div class="head-actions">${button(`${icon('plus')} Disciplina`,'subject-add','','sm')}${button(`${icon('plus')} Conteúdo`,'topic-add','','primary sm')}</div></div><div class="card-head"><h2 class="h3">Disciplinas <span class="muted small">(${db.subjects.length})</span></h2>${ui.librarySubject!=='all'?button('Mostrar todas','library-all','','sm ghost'):''}</div><div class="subject-grid">
     ${db.subjects.map(s=>`<div class="card subject-tile ${ui.librarySubject===s.id?'active':''}"><div class="tile-top"><button class="btn plain" style="color:${s.color};padding:0" data-action="library-subject" data-id="${s.id}" aria-label="Ver ${H(s.name)}">${icon('book','lg')}</button><div class="inline-actions">${button(icon('edit','sm'),'subject-edit',`data-id="${s.id}"`,'plain sm')}${button(icon('trash','sm'),'subject-delete',`data-id="${s.id}"`,'plain sm')}</div></div><button class="btn ghost" style="text-align:left;justify-content:flex-start;padding:0;min-height:0" data-action="library-subject" data-id="${s.id}"><strong>${H(s.name)}</strong></button><div class="small muted">${countsFor(s.id)} conteúdos ${s.exam?`· ${H(s.exam)}`:''}</div></div>`).join('')}</div>
     <div class="card-head"><h2 class="h3">Conteúdos <span class="muted small">(${filtered.length})</span></h2></div><div class="toolbar"><div class="searchbox">${icon('search')}<input id="library-search" value="${H(ui.librarySearch)}" placeholder="Buscar conteúdos..." aria-label="Buscar conteúdos"></div><select class="filter-select" id="library-filter" aria-label="Filtrar disciplina">${subjOpts(ui.librarySubject,true)}</select></div>
     ${filtered.length?`<div class="topic-grid">${filtered.map(t=>`<div class="card topic-tile"><span class="color-edge" style="background:${subjectColor(t.subjectId)}"></span><div class="grow"><div class="strong truncate">${H(t.title)}</div><div class="small muted">${H(subjectName(t.subjectId))} · ${t.paused?'Pausado':`Revisão ${fmt(t.dueDate)}`}</div><div style="margin-top:7px">${badge(t.paused?'Pausado':reviewState(t)==='overdue'?'Atrasado':reviewState(t)==='today'?'Revisar hoje':'Em dia',t.paused?'grey':reviewState(t)==='overdue'?'red':reviewState(t)==='today'?'yellow':'green')} ${badge(`${t.reviewCount||0} revisões`,'grey')}</div></div><div class="inline-actions">${button(icon('edit','sm'),'topic-edit',`data-id="${t.id}"`,'sm square')}${button(icon('chevron','sm'),'topic-details',`data-id="${t.id}"`,'sm square')}</div></div>`).join('')}</div>`:empty('book','Nenhum conteúdo encontrado','Adicione o que você estudou, com disciplina, data e nível de dificuldade.','topic-add','Adicionar conteúdo')}`;
  }
  const flashDue = () => db.flashcards.filter(f=>f.dueDate<=today());
  function flashPage(){
    if(ui.activeFlash) return flashSessionPage();
    const cards=db.flashcards.filter(f=>ui.flashSubject==='all'||tById(f.topicId)?.subjectId===ui.flashSubject);
    const dueCards=cards.filter(f=>f.dueDate<=today());
    return `<div class="head-row"><div><div class="eyebrow">LEMBRANÇA ATIVA</div><h1 class="h1">Flashcards</h1><p class="section-sub">Pergunte, tente lembrar e revele a resposta. O intervalo muda conforme sua avaliação.</p></div><div class="head-actions">${button(`${icon('plus')} Criar cartão`,'flash-add','','primary')}</div></div>
    <div class="stat-grid">${stat('Total de cartões',cards.length,'No filtro atual','card','var(--accent)')}${stat('Cartões devidos',dueCards.length,'Hoje e atrasados','calendar','var(--yellow)')}${stat('Respondidos hoje',db.flashReviews.filter(r=>localDay(r.at)===today()).length,'Revisões de flashcards','check','var(--green)')}${stat('Domínio alto',cards.filter(f=>(f.step||0)>=4).length,'Intervalos mais longos','target','var(--cyan)')}</div>
    <div class="card card-pad" style="margin-bottom:17px"><div class="between wrap"><div><h2 class="h3">Hora de recordar</h2><p class="section-sub">${dueCards.length?`${dueCards.length} cartões aguardando sua resposta.`:'Você está em dia com os cartões deste filtro.'}</p></div><div class="flex">${button(`${icon('play')} Estudar devidos`,'flash-start','', 'primary')}${button('Revisar todos','flash-start','data-all="yes"','sm')}</div></div></div>
    <div class="card card-pad"><div class="card-head"><h2 class="h3">Meus cartões</h2><select class="filter-select" id="flash-filter">${subjOpts(ui.flashSubject,true)}</select></div>${cards.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Frente</th><th>Conteúdo</th><th>Próxima revisão</th><th></th></tr></thead><tbody>${cards.map(f=>`<tr><td class="strong">${H(f.front).slice(0,135)}</td><td class="muted">${H(topicName(f.topicId))}</td><td>${fmt(f.dueDate)}</td><td><div class="inline-actions">${button(icon('edit','sm'),'flash-edit',`data-id="${f.id}"`,'sm square')}${button(icon('trash','sm'),'flash-delete',`data-id="${f.id}"`,'sm square')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('card','Nenhum flashcard','Crie perguntas de memorização vinculadas aos conteúdos estudados.','flash-add','Criar primeiro flashcard')}</div>`;
  }
  function flashSessionPage(){
    const q=ui.activeFlash;
    if(q.index>=q.ids.length)return `<div class="card card-pad" style="max-width:700px;margin:40px auto;text-align:center">${empty('check','Sessão finalizada',`Você revisou ${q.results.length} cartões nesta sessão.`)}<h2 class="h2" style="margin:14px 0">${q.results.filter(r=>r.grade==='good'||r.grade==='easy').length} lembrados sem dificuldade</h2>${button('Voltar aos flashcards','flash-end','','primary')}</div>`;
    const f=db.flashcards.find(f=>f.id===q.ids[q.index]);if(!f){q.index++;return flashSessionPage();}
    return `<div class="head-row"><div><div class="eyebrow">SESSÃO DE FLASHCARDS</div><h1 class="h1">Recordação ativa</h1><p class="section-sub">Cartão ${q.index+1} de ${q.ids.length} · ${H(topicName(f.topicId))}</p></div>${button(`${icon('close')} Encerrar`,'flash-end','','sm')}</div><div class="progress-track" style="margin-bottom:20px"><div class="progress-fill" style="width:${100*q.index/q.ids.length}%"></div></div>
     <button class="card flash-stage" style="width:100%;color:var(--text)" data-action="flash-flip" aria-label="${q.flipped?'Voltar à pergunta':'Revelar resposta'}"><div class="eyebrow">${q.flipped?'RESPOSTA':'PERGUNTA'}</div><div class="question">${H(f.front)}</div>${q.flipped?`<div class="sep" style="width:110px"></div><div class="answer green">${H(f.back)}</div>`:`<div class="small muted" style="margin-top:12px">Toque no cartão para revelar a resposta</div>`}</button>
     ${q.flipped?`<div class="grade-row">${gradeButtons('flash-grade')}</div>`:`<div style="text-align:center;margin-top:18px">${button(`${icon('refresh')} Revelar resposta`,'flash-flip','','primary')}</div>`}`;
  }
  function gradeButtons(action){return [['again','Não lembrei','1 dia'],['hard','Difícil','Intervalo curto'],['good','Bom','Próximo intervalo'],['easy','Fácil','Intervalo maior']].map(([grade,label,desc])=>`<button class="grade ${grade}" data-action="${action}" data-grade="${grade}">${label}<span>${desc}</span></button>`).join('');}
  function questionsPage(){
    if(ui.quiz)return quizPage();
    const qs=db.questions.filter(q=>ui.questionSubject==='all'||tById(q.topicId)?.subjectId===ui.questionSubject);
    const attempts=last30(db.quizAttempts,'at',30),pct=attempts.length?Math.round(100*attempts.filter(a=>a.correct).length/attempts.length):0;
    return `<div class="head-row"><div><div class="eyebrow">PRÁTICA COM QUESTÕES</div><h1 class="h1">Banco de questões</h1><p class="section-sub">Cadastre suas questões de múltipla escolha e pratique com correção e registro automático de erros.</p></div><div class="head-actions">${button(`${icon('plus')} Nova questão`,'question-add','','primary')}</div></div>
     <div class="stat-grid">${stat('Questões cadastradas',qs.length,'No filtro atual','target','var(--accent)')}${stat('Respostas em 30 dias',attempts.length,'Tentativas registradas','check','var(--green)')}${stat('Taxa de acerto',attempts.length?`${pct}%`:'—','Em todas as disciplinas','chart','var(--cyan)')}${stat('Erros para corrigir',db.errors.filter(e=>!e.resolved).length,'Caderno de erros','alert','var(--red)')}</div>
     <div class="card card-pad" style="margin-bottom:18px"><div class="between wrap"><div><h2 class="h3">Prática ativa</h2><p class="section-sub">As questões são embaralhadas. Revise a explicação após responder.</p></div>${button(`${icon('play')} Iniciar simulado`,'quiz-start','','primary')}</div><div class="toolbar" style="margin:14px 0 0"><select class="filter-select" id="question-filter">${subjOpts(ui.questionSubject,true)}</select><span class="small muted">${qs.length} questão(ões) disponíveis</span></div></div>
     <div class="card card-pad"><div class="card-head"><h2 class="h3">Questões cadastradas</h2></div>${qs.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Enunciado</th><th>Conteúdo</th><th>Gabarito</th><th></th></tr></thead><tbody>${qs.map(q=>`<tr><td class="strong">${H(q.prompt).slice(0,130)}${q.prompt.length>130?'…':''}</td><td class="muted">${H(topicName(q.topicId))}</td><td>${'ABCD'[q.correct]}</td><td><div class="inline-actions">${button(icon('edit','sm'),'question-edit',`data-id="${q.id}"`,'sm square')}${button(icon('trash','sm'),'question-delete',`data-id="${q.id}"`,'sm square')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('target','Seu banco está vazio','Cadastre questões de livros, simulados ou provas para praticar no próprio aplicativo.','question-add','Cadastrar questão')}</div>`;
  }
  function quizPage(){
    const q=ui.quiz;
    if(q.index>=q.ids.length){const right=q.results.filter(r=>r.correct).length,n=q.results.length;return `<div class="card card-pad" style="max-width:680px;margin:50px auto;text-align:center"><div class="empty-icon">${icon('target','xl')}</div><div class="eyebrow">SIMULADO CONCLUÍDO</div><h1 class="h1" style="margin:13px">${right} de ${n} acertos</h1><h2 class="h2 green">${n?Math.round(100*right/n):0}% de aproveitamento</h2><p class="muted">As questões erradas foram adicionadas automaticamente ao caderno de erros.</p>${button('Voltar ao banco de questões','quiz-end','','primary')}</div>`;}
    const item=db.questions.find(x=>x.id===q.ids[q.index]);if(!item){q.index++;return quizPage();}
    return `<div class="head-row"><div><div class="eyebrow">SIMULADO</div><h1 class="h1">Questão ${q.index+1} de ${q.ids.length}</h1><p class="section-sub">${H(subjectName(tById(item.topicId)?.subjectId))} · ${H(topicName(item.topicId))}</p></div>${button(`${icon('close')} Sair`,'quiz-end','','sm')}</div><div class="progress-track" style="margin-bottom:20px"><div class="progress-fill" style="width:${100*q.index/q.ids.length}%"></div></div>
     <div class="card card-pad"><h2 class="h2 cut-text" style="margin:8px 0 25px;line-height:1.55">${H(item.prompt)}</h2><div class="choice-grid">${item.options.map((answer,i)=>`<button class="choice ${q.answered?(i===item.correct?'correct':i===q.selected?'wrong':''):''}" data-action="quiz-answer" data-option="${i}" ${q.answered?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${H(answer)}</span></button>`).join('')}</div>
     ${q.answered?`<div class="notice" style="margin-top:17px;border-color:${q.selected===item.correct?'var(--green)':'var(--red)'}">${icon(q.selected===item.correct?'check':'info')}<div><strong>${q.selected===item.correct?'Resposta correta!':`Resposta incorreta. Gabarito: ${'ABCD'[item.correct]}.`}</strong>${item.explanation?`<div class="cut-text" style="margin-top:6px">${H(item.explanation)}</div>`:''}</div></div><div style="text-align:right;margin-top:17px">${button(q.index===q.ids.length-1?'Ver resultado':'Próxima questão '+icon('arrow'),'quiz-next','','primary')}</div>`:''}</div>`;
  }
  function errorsPage(){const es=db.errors.filter(e=>ui.errorFilter==='all'||(ui.errorFilter==='open'?!e.resolved:e.resolved)).sort((a,b)=>b.at.localeCompare(a.at));return `<div class="head-row"><div><div class="eyebrow">APRENDER COM OS ERROS</div><h1 class="h1">Caderno de erros</h1><p class="section-sub">Encontre seus pontos fracos e registre como evitar os mesmos erros.</p></div><div class="head-actions">${button(`${icon('plus')} Registrar erro`,'error-add','','primary')}</div></div>
   <div class="stat-grid">${stat('Pendentes',db.errors.filter(e=>!e.resolved).length,'Para estudar novamente','alert','var(--red)')}${stat('Corrigidos',db.errors.filter(e=>e.resolved).length,'Erros compreendidos','check','var(--green)')}${stat('Erros totais',db.errors.length,'Registrados desde o início','book','var(--accent)')}${stat('Acertos nas questões',db.quizAttempts.filter(a=>a.correct).length,'Todas as tentativas','target','var(--cyan)')}</div>
   <div class="toolbar"><div class="seg">${[['open','Pendentes'],['resolved','Resolvidos'],['all','Todos']].map(([id,label])=>`<button class="${ui.errorFilter===id?'selected':''}" data-action="error-filter" data-filter="${id}">${label}</button>`).join('')}</div></div>
   <div class="card card-pad">${es.length?`<div class="stack">${es.map(e=>`<div class="task" style="align-items:start"><div class="task-icon" style="background:${e.resolved?'#41d0ac22':'#ff829122'};color:${e.resolved?'var(--green)':'var(--red)'}">${icon(e.resolved?'check':'alert')}</div><div class="grow"><div class="strong cut-text">${H(e.description)}</div><div class="task-sub">${H(topicName(e.topicId))} · ${fmt(localDay(e.at))}</div>${e.correction?`<div class="small muted cut-text" style="margin-top:8px">Correção: ${H(e.correction)}</div>`:''}</div><div class="inline-actions">${button(icon('edit','sm'),'error-edit',`data-id="${e.id}"`,'sm square')}${button(icon(e.resolved?'refresh':'check','sm'),'error-toggle',`data-id="${e.id}"`,'sm square')}${button(icon('trash','sm'),'error-delete',`data-id="${e.id}"`,'sm square')}</div></div>`).join('')}</div>`:empty('check','Nada por aqui',ui.errorFilter==='open'?'Seus erros pendentes vão aparecer aqui.':'Não há registros para o filtro escolhido.','error-add','Registrar erro')}</div>`;}
  function statsPage(){
    const days=ui.statsRange,from=addDays(today(),-(days-1));const reviewed=db.reviews.filter(r=>localDay(r.at)>=from),studies=db.studySessions.filter(s=>s.date>=from),quizzes=db.quizAttempts.filter(a=>localDay(a.at)>=from);
    const learned=total(studies,s=>Number(s.minutes)||0),revised=total(reviewed,r=>Number(r.elapsed)||0);
    const recall=reviewed.length?Math.round(100*reviewed.filter(r=>['good','easy'].includes(r.grade)).length/reviewed.length):0;
    const accuracy=quizzes.length?Math.round(100*quizzes.filter(a=>a.correct).length/quizzes.length):0;
    const activityDays=Array.from({length:days},(_,i)=>addDays(from,i));const usage=d=>reviewed.filter(r=>localDay(r.at)===d).length+studies.filter(s=>s.date===d).length+db.flashReviews.filter(r=>localDay(r.at)===d).length;
    const activeDays=activityDays.filter(d=>usage(d)>0).length;
    const perSubject=db.subjects.map(s=>({...s,minutes:total(studies.filter(x=>tById(x.topicId)?.subjectId===s.id),x=>Number(x.minutes)||0)+total(reviewed.filter(r=>tById(r.topicId)?.subjectId===s.id),r=>Number(r.elapsed)||0)})).filter(s=>s.minutes>0).sort((a,b)=>b.minutes-a.minutes);
    const max=Math.max(1,...perSubject.map(s=>s.minutes));
    const gradesCount=['again','hard','good','easy'].map(g=>reviewed.filter(r=>r.grade===g).length);
    return `<div class="head-row"><div><div class="eyebrow">CONSISTÊNCIA E APRENDIZAGEM</div><h1 class="h1">Suas estatísticas</h1><p class="section-sub">Acompanhe os estudos, revisões e desempenho registrado no aplicativo.</p></div><div class="head-actions"><div class="seg">${[7,30,90].map(n=>`<button class="${days===n?'selected':''}" data-action="stats-range" data-value="${n}">${n} dias</button>`).join('')}</div></div></div>
    <div class="stat-grid">${stat('Tempo total',minutes(learned+revised),'Estudo + revisões','clock','var(--accent)')}${stat('Revisões feitas',reviewed.length,`${db.flashReviews.filter(r=>localDay(r.at)>=from).length} flashcards à parte`,'check','var(--green)')}${stat('Boa lembrança',reviewed.length?recall+'%':'—','Notas Bom e Fácil','target','var(--cyan)')}${stat('Acertos',quizzes.length?accuracy+'%':'—',`${quizzes.length} questões respondidas`,'chart','var(--yellow)')}</div>
    <div class="two-grid"><div class="card card-pad"><div class="card-head"><div><h2 class="h3">Calendário de atividade</h2><p class="section-sub">${activeDays} dias ativos nos últimos ${days} dias</p></div></div><div class="heatmap" style="grid-template-columns:repeat(${days===7?7:days===30?10:14},1fr)">${activityDays.map(d=>`<div class="heat-cell ${['','l1','l2','l3','l4'][Math.min(4,usage(d))]}" title="${fmt(d)}: ${usage(d)} atividades"></div>`).join('')}</div><div class="small muted" style="margin-top:14px">Atividade: estudos, revisões e flashcards</div><div class="sep"></div><div class="between"><span class="muted small">Dias com atividades</span><strong>${activeDays} / ${days}</strong></div><div class="progress-track" style="margin-top:8px"><div class="progress-fill" style="width:${100*activeDays/days}%"></div></div></div>
    <div class="card card-pad"><div class="card-head"><div><h2 class="h3">Qualidade da lembrança</h2><p class="section-sub">Como você avaliou as últimas revisões</p></div></div><div class="flex" style="gap:21px;justify-content:center"><div class="circle-meter" style="--percent:${recall}%"><strong>${reviewed.length?recall+'%':'—'}</strong></div><div class="donut-legend">${['Não lembrei','Difícil','Bom','Fácil'].map((name,i)=>`<div class="between small"><span class="flex"><span class="subject-dot" style="background:${['var(--red)','var(--yellow)','var(--accent)','var(--green)'][i]}"></span>${name}</span><strong>${gradesCount[i]}</strong></div>`).join('')}</div></div></div></div>
    <div class="two-grid" style="margin-top:18px"><div class="card card-pad"><div class="card-head"><h2 class="h3">Tempo por disciplina</h2></div>${perSubject.length?perSubject.map(s=>`<div style="margin-bottom:17px"><div class="between small"><span class="flex"><span class="subject-dot" style="background:${s.color}"></span>${H(s.name)}</span><strong>${minutes(s.minutes)}</strong></div><div class="subject-bar"><div style="width:${100*s.minutes/max}%;background:${s.color}"></div></div></div>`).join(''):empty('clock','Sem registros','Registre seus estudos para descobrir a distribuição de tempo por disciplina.')}</div>
    <div class="card card-pad"><div class="card-head"><h2 class="h3">Indicadores gerais</h2></div>${[['Conteúdos cadastrados',db.topics.length],['Conteúdos ativos',activeTopics().length],['Revisões atrasadas',overdue().length],['Flashcards criados',db.flashcards.length],['Questões no banco',db.questions.length],['Erros resolvidos',db.errors.filter(e=>e.resolved).length]].map(([label,value])=>`<div class="mini-stat between"><span class="small muted">${label}</span><strong>${value}</strong></div>`).join('')}</div></div><div class="notice" style="margin-top:18px">${icon('info')}A porcentagem de “boa lembrança” representa suas autoavaliações, não uma medida científica de retenção. Estimativas de domínio dependem da honestidade ao responder.</div>`;
  }
  function settingsPage(){
    return `<div class="head-row"><div><div class="eyebrow">PERSONALIZE SEU ESTUDO</div><h1 class="h1">Ajustes</h1><p class="section-sub">Adapte os intervalos, horários, aparência e cuidados com seus dados.</p></div></div>
    <div class="card settings-group"><h2 class="h3" style="margin-bottom:10px">Preferências de estudo</h2><form data-form="settings"><div class="field-grid"><div class="field"><label>Meta diária de revisões (minutos)</label><input name="dailyCap" type="number" min="5" max="600" required value="${db.settings.dailyCap}"><div class="field-help">Usada para estimar sobrecarga ao distribuir pendências.</div></div><div class="field"><label>Duração padrão da revisão (minutos)</label><input name="defaultReviewMinutes" type="number" min="1" max="180" required value="${db.settings.defaultReviewMinutes}"></div><div class="field span-2"><label>Intervalos base (dias separados por vírgula)</label><input name="intervals" value="${db.settings.intervals.join(', ')}" required><div class="field-help">Ex.: 1, 3, 7, 15, 30, 60, 120, 240. O intervalo real depende da dificuldade marcada em cada revisão.</div></div></div><div class="modal-footer">${button(`${icon('check')} Salvar preferências`,'submit-settings','','primary')}</div></form></div>
    <div class="card settings-group"><h2 class="h3" style="margin-bottom:7px">Aparência e avisos</h2><div class="settings-row"><div><div class="strong">Tema do aplicativo</div><p>Escolha o visual ideal para estudar.</p></div>${button(db.settings.theme==='dark'?`${icon('moon')} Escuro`:`${icon('sun')} Claro`,'theme','','sm')}</div><div class="settings-row"><div><div class="strong">Notificações no navegador</div><p>Avisos ao abrir ou manter o aplicativo em execução. Não há alertas garantidos quando ele estiver fechado.</p></div>${button(db.settings.notifications?'Ativadas':'Ativar','notify-enable','','sm')}</div><div class="settings-row"><div><div class="strong">Instalar no celular ou computador</div><p>Requer HTTPS e navegador compatível. A instalação pode aparecer no menu do navegador.</p></div>${button(`${icon('download')} Instalar`,'install','','sm')}</div></div>
    <div class="card settings-group"><h2 class="h3" style="margin-bottom:8px">Seus dados e privacidade</h2><div class="notice">${icon('info')}Tudo fica salvo neste navegador/dispositivo. O aplicativo não possui conta nem servidor. Limpar dados do site ou trocar de celular pode apagar o histórico: exporte backups regularmente.</div><div class="settings-row"><div><div class="strong">Exportar backup (.json)</div><p>Inclui disciplinas, revisões, questões, flashcards e histórico.</p></div>${button(`${icon('download')} Exportar`,'export','','sm')}</div><div class="settings-row"><div><div class="strong">Importar backup</div><p>Substitui os dados atuais pelo arquivo escolhido (com confirmação).</p></div>${button(`${icon('upload')} Importar`,'import','','sm')}</div><div class="settings-row"><div><div class="strong red">Apagar todos os dados</div><p>Restaura o aplicativo. Requer confirmação explícita.</p></div>${button(`${icon('trash')} Restaurar`,'reset','','danger sm')}</div></div>
    <div class="small muted" style="padding:6px">Revisa+ 1.0 · PWA offline-first · Repetição espaçada adaptativa · Feito para seus estudos.</div>`;
  }
  function openModal(title,body,wide=false){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${H(title)}"><div class="modal-top"><h2>${H(title)}</h2>${button(icon('close'),'modal-close','','plain sm')}</div>${body}</section></div>`;setTimeout(()=>document.querySelector('#modal-root input:not([type=hidden]),#modal-root select,#modal-root textarea')?.focus(),30);}
  const closeModal=()=>{document.getElementById('modal-root').innerHTML='';currentReview=null;};
  const modalFooter=(label='Salvar')=>`<div class="modal-footer">${button('Cancelar','modal-close','','sm')}<button class="btn primary" type="submit">${icon('check')} ${label}</button></div>`;
  function subjectModal(id){const s=id?sById(id):null;if(id&&!s)return;openModal(s?'Editar disciplina':'Nova disciplina',`<form data-form="subject" data-id="${s?.id||''}"><div class="field"><label>Nome da disciplina *</label><input name="name" maxlength="65" required placeholder="Ex.: Matemática" value="${H(s?.name||'')}"></div><div class="field-grid"><div class="field"><label>Cor de identificação</label><input name="color" type="color" value="${H(s?.color||'#7d89f9')}" style="padding:5px;height:44px"></div><div class="field"><label>Concurso / objetivo (opcional)</label><input name="exam" maxlength="75" placeholder="Ex.: EsPCEx" value="${H(s?.exam||'')}"></div></div>${modalFooter(s?'Salvar disciplina':'Criar disciplina')}</form>`);}
  function topicModal(id){const t=id?tById(id):null;if(id&&!t)return;if(!db.subjects.length){toast('Cadastre uma disciplina primeiro.');subjectModal();return;}
   openModal(t?'Editar conteúdo':'Cadastrar conteúdo',`<form data-form="topic" data-id="${t?.id||''}"><div class="field-grid"><div class="field span-2"><label>Conteúdo estudado *</label><input name="title" maxlength="140" required placeholder="Ex.: Frações — operações básicas" value="${H(t?.title||'')}"></div><div class="field"><label>Disciplina *</label><select name="subjectId" required>${subjOpts(t?.subjectId||db.subjects[0]?.id)}</select></div><div class="field"><label>Data do estudo *</label><input type="date" name="studyDate" required value="${H(t?.studyDate||today())}"></div><div class="field"><label>Dificuldade inicial</label><select name="difficulty">${opt(1,t?.difficulty||2,'Fácil')}${opt(2,t?.difficulty||2,'Média')}${opt(3,t?.difficulty||2,'Difícil')}</select></div><div class="field"><label>Prioridade</label><select name="priority">${opt(1,t?.priority||2,'Baixa')}${opt(2,t?.priority||2,'Normal')}${opt(3,t?.priority||2,'Alta')}</select></div><div class="field"><label>Tempo estudado (min)</label><input type="number" min="0" max="600" name="studyMinutes" value="${t?'0':'50'}"></div><div class="field"><label>Previsão por revisão (min)</label><input type="number" min="1" max="180" name="reviewMinutes" value="${t?.reviewMinutes||db.settings.defaultReviewMinutes}" required></div><div class="field span-2"><label>Material, capítulo ou página</label><input maxlength="180" name="source" value="${H(t?.source||'')}" placeholder="Ex.: TQM · Capítulo 3 · Páginas 28–35"></div><div class="field span-2"><label>Anotações / resumo</label><textarea name="notes" placeholder="Escreva o que vale a pena recuperar durante as revisões.">${H(t?.notes||'')}</textarea></div>${t?`<div class="field span-2"><label class="checkline"><input type="checkbox" name="restart"> Reiniciar meu ciclo de revisões a partir da data escolhida</label></div>`:''}</div>${modalFooter(t?'Salvar alterações':'Criar e agendar revisões')}</form>`,true);
  }
  function studyModal(){if(!db.topics.length){toast('Cadastre um conteúdo antes de registrar seus estudos.');topicModal();return;}openModal('Registrar sessão de estudo',`<form data-form="study"><div class="field"><label>Conteúdo *</label><select name="topicId" required>${topicOpts(db.topics[0]?.id)}</select></div><div class="field-grid"><div class="field"><label>Data *</label><input name="date" type="date" value="${today()}" required></div><div class="field"><label>Duração (minutos) *</label><input name="minutes" type="number" min="1" max="600" value="45" required></div></div><div class="field"><label>Tipo</label><select name="kind"><option value="study">Estudo de teoria</option><option value="practice">Exercícios / prática</option></select></div><div class="field"><label class="checkline"><input type="checkbox" name="restart"> Recomeçar a revisão espaçada deste conteúdo</label><span class="field-help">Deixe desmarcado se apenas realizou exercícios adicionais.</span></div>${modalFooter('Registrar estudo')}</form>`);}
  function flashModal(id){const f=id?db.flashcards.find(x=>x.id===id):null;if(id&&!f)return;if(!db.topics.length){toast('Primeiro, adicione um conteúdo à biblioteca.');topicModal();return;}openModal(f?'Editar flashcard':'Novo flashcard',`<form data-form="flash" data-id="${f?.id||''}"><div class="field"><label>Conteúdo *</label><select name="topicId" required>${topicOpts(f?.topicId||db.topics[0].id)}</select></div><div class="field"><label>Frente — pergunta *</label><textarea name="front" required maxlength="1000" placeholder="Ex.: Qual é a propriedade fundamental das proporções?">${H(f?.front||'')}</textarea></div><div class="field"><label>Verso — resposta *</label><textarea name="back" required maxlength="1500" placeholder="Escreva a resposta que pretende recuperar da memória.">${H(f?.back||'')}</textarea></div>${modalFooter(f?'Atualizar cartão':'Criar flashcard')}</form>`);}
  function questionModal(id){const q=id?db.questions.find(x=>x.id===id):null;if(id&&!q)return;if(!db.topics.length){toast('Cadastre um conteúdo antes de adicionar questões.');topicModal();return;}openModal(q?'Editar questão':'Cadastrar questão',`<form data-form="question" data-id="${q?.id||''}"><div class="field"><label>Conteúdo *</label><select name="topicId" required>${topicOpts(q?.topicId||db.topics[0]?.id)}</select></div><div class="field"><label>Enunciado *</label><textarea maxlength="2500" name="prompt" required placeholder="Digite aqui o enunciado da questão.">${H(q?.prompt||'')}</textarea></div><div class="field-grid">${['A','B','C','D'].map((letter,i)=>`<div class="field"><label>Alternativa ${letter} *</label><textarea name="o${i}" required maxlength="900" style="min-height:65px" placeholder="Alternativa ${letter}">${H(q?.options?.[i]||'')}</textarea></div>`).join('')}</div><div class="field"><label>Gabarito *</label><select name="correct" required>${[0,1,2,3].map(i=>opt(i,q?.correct??0,'Alternativa '+ 'ABCD'[i])).join('')}</select></div><div class="field"><label>Explicação / resolução (opcional)</label><textarea name="explanation" maxlength="4000" placeholder="Por que esta alternativa está correta?">${H(q?.explanation||'')}</textarea></div>${modalFooter(q?'Salvar questão':'Cadastrar questão')}</form>`,true);}
  function errorModal(id){const e=id?db.errors.find(x=>x.id===id):null;if(id&&!e)return;if(!db.topics.length){toast('Cadastre um conteúdo antes de registrar erros.');topicModal();return;}openModal(e?'Editar registro de erro':'Registrar erro',`<form data-form="error" data-id="${e?.id||''}"><div class="field"><label>Conteúdo *</label><select name="topicId" required>${topicOpts(e?.topicId||db.topics[0]?.id)}</select></div><div class="field"><label>O que você errou? *</label><textarea name="description" required maxlength="3000" placeholder="Descreva a dúvida, erro de cálculo ou conceito.">${H(e?.description||'')}</textarea></div><div class="field"><label>Correção / como evitar novamente</label><textarea name="correction" maxlength="3000" placeholder="Qual seria o raciocínio correto?">${H(e?.correction||'')}</textarea></div>${modalFooter(e?'Salvar correção':'Registrar erro')}</form>`);}
  function topicDetails(id){const t=tById(id);if(!t)return;const history=db.reviews.filter(r=>r.topicId===id).sort((a,b)=>b.at.localeCompare(a.at));openModal('Detalhes do conteúdo',`<div class="between wrap"><div><h2 class="h2">${H(t.title)}</h2><p class="section-sub">${H(subjectName(t.subjectId))} · Estudado em ${fmt(t.studyDate)}</p></div>${badge(t.paused?'Pausado':`Revisão ${fmt(t.dueDate)}`,t.paused?'grey':'blue')}</div>
    <div class="stat-grid" style="grid-template-columns:repeat(3,1fr)">${stat('Revisões',t.reviewCount||0,'Registradas','refresh','var(--accent)')}${stat('Sequência',t.streak||0,'Boas revisões','flame','var(--green)')}${stat('Intervalo',`${t.intervalDay||1}d`,'Atual','calendar','var(--yellow)')}</div>
    ${t.source?`<div class="small muted" style="margin:12px 0">${icon('book','sm')} Material: ${H(t.source)}</div>`:''}
    ${t.notes?`<div class="note-box" style="margin:10px 0">${H(t.notes)}</div>`:''}
    <h3 class="h3" style="margin:18px 0 10px">Histórico recente</h3>${history.length?history.slice(0,7).map(r=>`<div class="mini-stat between"><span class="small">${fmt(localDay(r.at))} · ${getGrade(r.grade)[0]}</span><span class="small muted">${Number(r.elapsed)||0} min</span></div>`).join(''):empty('clock','Nenhuma revisão ainda','O histórico surgirá após sua primeira revisão.')}
    <div class="modal-footer wrap">${button(icon('trash')+' Excluir','topic-delete',`data-id="${t.id}"`,'danger sm')}${button(t.paused?'Ativar':'Pausar','topic-pause',`data-id="${t.id}"`,'sm')}${button('Alterar data','topic-date',`data-id="${t.id}"`,'sm')}${button('Editar','topic-edit',`data-id="${t.id}"`,'sm')}${button('Revisar agora','review-start',`data-id="${t.id}"`,'primary sm')}</div>`,true);}
  function reviewModal(id){const t=tById(id);if(!t)return;if(t.paused){toast('Ative o conteúdo para revisá-lo.');return;}currentReview={id,start:Date.now()};openModal('Revisão ativa',`<div class="between wrap"><div><div class="eyebrow">${H(subjectName(t.subjectId))} · REVISÃO ${(t.reviewCount||0)+1}</div><h2 class="h2" style="margin-top:9px">${H(t.title)}</h2><p class="section-sub">Prevista para ${fmt(t.dueDate)} · ${reviewMinutes(t)} min estimados</p></div>${badge(t.difficulty===3?'Assunto difícil':t.difficulty===1?'Assunto fácil':'Dificuldade média',t.difficulty===3?'red':'blue')}</div>
    <div class="notice" style="margin:17px 0">${icon('target')}Antes de olhar suas anotações, tente explicar o assunto em voz alta ou resolver 2–5 exercícios sem consultar o material. Depois avalie a dificuldade real.</div>
    ${t.source?`<div class="small muted" style="margin:12px 0">Material: ${H(t.source)}</div>`:''}<div style="margin:13px 0">${button(`${icon('book')} ${t.notes?'Mostrar / ocultar anotações':'Sem anotações cadastradas'}`,'review-notes','', 'sm')}</div><div id="review-notes-box" hidden>${t.notes?`<div class="note-box">${H(t.notes)}</div>`:'<div class="small muted">Adicione anotações na biblioteca para consultá-las durante a revisão.</div>'}</div>
    <div class="field-grid" style="margin-top:16px"><div class="field"><label>Questões resolvidas (opcional)</label><input id="review-q-total" type="number" min="0" max="999" placeholder="Ex.: 5"></div><div class="field"><label>Questões corretas (opcional)</label><input id="review-q-right" type="number" min="0" max="999" placeholder="Ex.: 4"></div><div class="field span-2"><label>Anotação sobre esta revisão (opcional)</label><textarea id="review-note" placeholder="O que você esqueceu? O que precisa reforçar?" style="min-height:65px"></textarea></div></div>
    <div class="small muted" style="margin-top:17px">Como foi recuperar o conteúdo sem consultar?</div><div class="grade-row">${gradeButtons('review-grade')}</div>`,true);}
  function rescheduleModal(){const list=overdue();if(!list.length){toast('Não há revisões atrasadas para distribuir.');return;}const backlog=total(list,t=>reviewMinutes(t));openModal('Distribuir revisões atrasadas',`<div class="notice">${icon('info')}Esta ação reorganiza apenas as <strong>${list.length} revisões já atrasadas</strong>, começando hoje, dentro da meta de ${db.settings.dailyCap} minutos por dia, quando possível. As datas originais mudarão; as revisões concluídas permanecem registradas.</div><p class="muted small" style="margin:16px 0">Tempo estimado do atraso: <strong>${minutes(backlog)}</strong>. Os conteúdos de prioridade alta e com mais atraso entram primeiro.</p><div class="modal-footer">${button('Cancelar','modal-close','','sm')}${button('Distribuir revisões','reschedule-confirm','','primary')}</div>`);}
  function topicDateModal(id){const t=tById(id);if(!t)return;openModal('Alterar data de revisão',`<form data-form="topic-date" data-id="${t.id}"><div class="field"><label>Próxima revisão de ${H(t.title)}</label><input name="dueDate" type="date" required value="${t.dueDate}"></div><div class="notice">${icon('info')}Alterar a data não apaga seu histórico e não altera o nível de dificuldade registrado.</div>${modalFooter('Salvar data')}</form>`);}
  function doGrade(id,grade,mode){const target=mode==='flash'?db.flashcards.find(f=>f.id===id):tById(id);if(!target)return;
    const scheme=db.settings.intervals,step=target.step||0;
    let newStep,interval;
    if(grade==='again'){newStep=0;interval=1;target.streak=0;target.lapses=(target.lapses||0)+1;}
    else if(grade==='hard'){newStep=Math.max(0,step);interval=Math.max(1,Math.round((target.intervalDay||scheme[Math.min(step,scheme.length-1)])*.65));target.streak=0;}
    else if(grade==='good'){newStep=Math.min(scheme.length-1,step+1);interval=scheme[newStep];target.streak=(target.streak||0)+1;}
    else {newStep=Math.min(scheme.length-1,step+2);interval=Math.max(1,Math.round(scheme[newStep]*1.15));target.streak=(target.streak||0)+1;}
    target.step=newStep;target.intervalDay=interval;target.dueDate=addDays(today(),interval);target.lastReviewedAt=new Date().toISOString();target.reviewCount=(target.reviewCount||0)+1;return interval;
  }
  function gradeReview(grade){if(!currentReview)return;const t=tById(currentReview.id);if(!t)return;const totalQ=document.getElementById('review-q-total').value,rightQ=document.getElementById('review-q-right').value;
   if((totalQ||rightQ)&&(totalQ===''||rightQ===''||Number(rightQ)>Number(totalQ))){toast('Preencha corretamente os totais de questões e acertos.');return;}
   const note=document.getElementById('review-note').value.trim(),oldDate=t.dueDate,elapsed=Math.max(1,Math.round((Date.now()-currentReview.start)/60000));
   const interval=doGrade(t.id,grade,'topic');
   db.reviews.push({id:uid(),topicId:t.id,at:new Date().toISOString(),grade,elapsed,oldDue:oldDate,newDue:t.dueDate,note,questions:Number(totalQ)||0,right:Number(rightQ)||0});
   if(note&&grade==='again')db.errors.push({id:uid(),topicId:t.id,at:new Date().toISOString(),description:note,correction:'',resolved:false,source:'review'});
   save();closeModal();render();toast(`Revisão registrada! Próxima em ${interval} dia(s), em ${fmt(t.dueDate)}.`);
  }
  function confirmDelete(message){return window.confirm(message);}
  function shuffle(arr){const result=[...arr];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
  function redistribute(){const list=overdue().sort((a,b)=>(b.priority||2)-(a.priority||2)||a.dueDate.localeCompare(b.dueDate));const occupied={};activeTopics().filter(t=>t.dueDate>=today()).forEach(t=>occupied[t.dueDate]=(occupied[t.dueDate]||0)+reviewMinutes(t));let last=0;
    list.forEach(t=>{let offset=-1;for(let i=0;i<30;i++){const d=addDays(today(),i);if((occupied[d]||0)+reviewMinutes(t)<=db.settings.dailyCap){offset=i;break;}}if(offset<0){let smallest=Infinity;for(let i=0;i<30;i++){const load=occupied[addDays(today(),i)]||0;if(load<smallest){smallest=load;offset=i;}}}const d=addDays(today(),offset);occupied[d]=(occupied[d]||0)+reviewMinutes(t);t.dueDate=d;last=Math.max(last,offset);});save();closeModal();render();toast(`${list.length} revisões distribuídas pelos próximos ${last+1} dia(s).`);}
  function exportData(){const payload=JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2);const blob=new Blob([payload],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`revisa-plus-backup-${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup JSON exportado. Guarde-o em um lugar seguro.');}
  function validImport(o){return o&&typeof o==='object'&&Number(o.version)===1&&LISTS.every(k=>Array.isArray(o[k]))&&o.settings&&typeof o.settings==='object'&&o.topics.every(t=>typeof t.id==='string'&&typeof t.title==='string')&&o.subjects.every(s=>typeof s.id==='string'&&typeof s.name==='string')&&o.questions.every(q=>Array.isArray(q.options)&&q.options.length===4);}
  async function importData(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('O arquivo é maior que 5 MB.');const parsed=JSON.parse(await file.text());if(!validImport(parsed))throw Error('Este arquivo não é um backup válido do Revisa+.');if(!window.confirm(`Importar ${parsed.topics.length} conteúdos, ${parsed.reviews.length} revisões e ${parsed.flashcards.length} flashcards? Isso SUBSTITUIRÁ todos os dados atuais. Faça um backup antes.`))return;const baseline=defaults();LISTS.forEach(k=>parsed[k]=Array.isArray(parsed[k])?parsed[k]:baseline[k]);parsed.settings={...baseline.settings,...parsed.settings};if(!Array.isArray(parsed.settings.intervals)||!parsed.settings.intervals.length)parsed.settings.intervals=baseline.settings.intervals;db=parsed;save();ui={...ui,page:'home',activeFlash:null,quiz:null,librarySubject:'all',flashSubject:'all',questionSubject:'all'};render();toast('Backup importado com sucesso.');}catch(e){toast(`Falha na importação: ${e.message}`);}finally{document.querySelector('#import-file').value='';}}
  async function enableNotifications(){if(!('Notification' in window)){toast('Este navegador não oferece notificações para esta página.');return;}if(!window.isSecureContext){toast('Ative as notificações com o aplicativo hospedado em HTTPS.');return;}try{const perm=await Notification.requestPermission();db.settings.notifications=perm==='granted';save();render();if(perm==='granted'){toast('Avisos ativados para quando o aplicativo estiver aberto.');notifyIfDue();}else toast('A permissão de notificações não foi concedida.');}catch(e){toast('Não foi possível pedir a permissão de notificações.');}}
  function notifyIfDue(){if(!db.settings.notifications||!('Notification' in window)||Notification.permission!=='granted')return;const n=due().length;if(!n)return;const key='revisaplus-last-notification';try{if(localStorage.getItem(key)===today())return;localStorage.setItem(key,today());new Notification('Revisa+ · revisões esperando',{body:`Você tem ${n} revisão(ões) pendentes. Abra o Revisa+ para continuar.`,icon:'./icon-192.png',tag:'revisaplus-due'});}catch(e){console.warn(e);}}
  async function installApp(){if(deferredInstall){deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;return;}toast('No Android: Chrome → menu ⋮ → Instalar app. No iPhone: Safari → Compartilhar → Adicionar à Tela de Início.');}
  function gradeFlash(grade){const q=ui.activeFlash;if(!q)return;const f=db.flashcards.find(x=>x.id===q.ids[q.index]);if(!f)return;doGrade(f.id,grade,'flash');db.flashReviews.push({id:uid(),flashId:f.id,topicId:f.topicId,at:new Date().toISOString(),grade});q.results.push({id:f.id,grade});q.index++;q.flipped=false;save();render();}
  function answerQuiz(option){const q=ui.quiz;if(!q||q.answered)return;const item=db.questions.find(x=>x.id===q.ids[q.index]);if(!item)return;const correct=option===item.correct;q.selected=option;q.answered=true;q.results.push({questionId:item.id,correct});db.quizAttempts.push({id:uid(),questionId:item.id,topicId:item.topicId,answer:option,correct,at:new Date().toISOString()});if(!correct){db.errors.push({id:uid(),topicId:item.topicId,questionId:item.id,description:item.prompt,correction:`Gabarito: ${'ABCD'[item.correct]} — ${item.options[item.correct]}.${item.explanation?' '+item.explanation:''}`,at:new Date().toISOString(),resolved:false,source:'quiz'});}save();render();}
  async function handleClick(event){const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
    switch(action){
    case 'go':go(el.dataset.page);break;
    case 'menu-toggle':ui.menu=!ui.menu;render();break;
    case 'menu-close':ui.menu=false;render();break;
    case 'theme':db.settings.theme=db.settings.theme==='dark'?'light':'dark';save();render();break;
    case 'modal-close':closeModal();break;
    case 'subject-add':subjectModal();break;
    case 'subject-edit':subjectModal(id);break;
    case 'subject-delete':{const s=sById(id);if(!s)break;if(countsFor(id)>0){toast('Mova ou exclua os conteúdos desta disciplina antes de apagá-la.');break;}if(confirmDelete(`Excluir a disciplina “${s.name}”?`)){db.subjects=db.subjects.filter(s=>s.id!==id);if(ui.librarySubject===id)ui.librarySubject='all';save();render();toast('Disciplina excluída.');}break;}
    case 'topic-add':topicModal();break;
    case 'topic-edit':topicModal(id);break;
    case 'topic-details':topicDetails(id);break;
    case 'topic-delete':{const t=tById(id);if(!t)break;if(confirmDelete(`Excluir definitivamente “${t.title}” e todo seu histórico, flashcards, questões e erros vinculados? Essa ação não pode ser desfeita.`)){const flashIds=new Set(db.flashcards.filter(f=>f.topicId===id).map(f=>f.id)),questionIds=new Set(db.questions.filter(q=>q.topicId===id).map(q=>q.id));db.topics=db.topics.filter(x=>x.id!==id);db.reviews=db.reviews.filter(x=>x.topicId!==id);db.studySessions=db.studySessions.filter(x=>x.topicId!==id);db.flashcards=db.flashcards.filter(x=>x.topicId!==id);db.flashReviews=db.flashReviews.filter(x=>!flashIds.has(x.flashId));db.questions=db.questions.filter(x=>x.topicId!==id);db.quizAttempts=db.quizAttempts.filter(x=>!questionIds.has(x.questionId));db.errors=db.errors.filter(x=>x.topicId!==id);save();closeModal();render();toast('Conteúdo e registros vinculados excluídos.');}break;}
    case 'topic-pause':{const t=tById(id);if(t){t.paused=!t.paused;save();closeModal();render();toast(t.paused?'Conteúdo pausado.':'Conteúdo reativado.');}break;}
    case 'topic-date':topicDateModal(id);break;
    case 'study-add':studyModal();break;
    case 'review-start':reviewModal(id);break;
    case 'review-notes':{const box=document.getElementById('review-notes-box');if(box)box.hidden=!box.hidden;break;}
    case 'review-grade':gradeReview(el.dataset.grade);break;
    case 'reschedule':rescheduleModal();break;
    case 'reschedule-confirm':redistribute();break;
    case 'month-prev':{const d=parseDay(ui.calendarMonth);d.setMonth(d.getMonth()-1);ui.calendarMonth=localDay(d);render();break;}
    case 'month-next':{const d=parseDay(ui.calendarMonth);d.setMonth(d.getMonth()+1);ui.calendarMonth=localDay(d);render();break;}
    case 'calendar-today':ui.calendarMonth=today().slice(0,7)+'-01';ui.calendarDay=today();render();break;
    case 'calendar-day':ui.calendarDay=el.dataset.day;ui.calendarMonth=ui.calendarDay.slice(0,7)+'-01';render();break;
    case 'library-subject':ui.librarySubject=id;render();break;
    case 'library-all':ui.librarySubject='all';render();break;
    case 'review-filter':ui.reviewFilter=el.dataset.filter;render();break;
    case 'flash-add':flashModal();break;
    case 'flash-edit':flashModal(id);break;
    case 'flash-delete':{const f=db.flashcards.find(x=>x.id===id);if(f&&confirmDelete('Excluir este flashcard e seu histórico de revisão?')){db.flashcards=db.flashcards.filter(x=>x.id!==id);db.flashReviews=db.flashReviews.filter(r=>r.flashId!==id);save();render();toast('Flashcard excluído.');}break;}
    case 'flash-start':{const cards=db.flashcards.filter(f=>(ui.flashSubject==='all'||tById(f.topicId)?.subjectId===ui.flashSubject)&&(el.dataset.all==='yes'||f.dueDate<=today()));if(!cards.length){toast('Não há cartões disponíveis para esta sessão.');break;}ui.activeFlash={ids:shuffle(cards.map(f=>f.id)),index:0,flipped:false,results:[]};render();break;}
    case 'flash-flip':if(ui.activeFlash){ui.activeFlash.flipped=!ui.activeFlash.flipped;render();}break;
    case 'flash-grade':gradeFlash(el.dataset.grade);break;
    case 'flash-end':ui.activeFlash=null;render();break;
    case 'question-add':questionModal();break;
    case 'question-edit':questionModal(id);break;
    case 'question-delete':{const q=db.questions.find(x=>x.id===id);if(q&&confirmDelete('Excluir esta questão e suas tentativas registradas?')){db.questions=db.questions.filter(x=>x.id!==id);db.quizAttempts=db.quizAttempts.filter(x=>x.questionId!==id);db.errors=db.errors.filter(x=>x.questionId!==id);save();render();toast('Questão excluída.');}break;}
    case 'quiz-start':{const qs=db.questions.filter(q=>ui.questionSubject==='all'||tById(q.topicId)?.subjectId===ui.questionSubject);if(!qs.length){toast('Cadastre uma questão antes de iniciar o simulado.');break;}ui.quiz={ids:shuffle(qs.map(q=>q.id)),index:0,selected:null,answered:false,results:[]};render();break;}
    case 'quiz-answer':answerQuiz(Number(el.dataset.option));break;
    case 'quiz-next':if(ui.quiz){ui.quiz.index++;ui.quiz.answered=false;ui.quiz.selected=null;render();}break;
    case 'quiz-end':ui.quiz=null;render();break;
    case 'error-add':errorModal();break;
    case 'error-edit':errorModal(id);break;
    case 'error-filter':ui.errorFilter=el.dataset.filter;render();break;
    case 'error-toggle':{const e=db.errors.find(x=>x.id===id);if(e){e.resolved=!e.resolved;e.resolvedAt=e.resolved?new Date().toISOString():null;save();render();toast(e.resolved?'Erro marcado como resolvido.':'Erro reaberto.');}break;}
    case 'error-delete':if(confirmDelete('Excluir este registro de erro?')){db.errors=db.errors.filter(x=>x.id!==id);save();render();toast('Registro excluído.');}break;
    case 'stats-range':ui.statsRange=Number(el.dataset.value);render();break;
    case 'submit-settings':document.querySelector('form[data-form="settings"]')?.requestSubmit();break;
    case 'notify-enable':await enableNotifications();break;
    case 'install':await installApp();break;
    case 'export':exportData();break;
    case 'import':document.getElementById('import-file').click();break;
    case 'reset':{if(confirmDelete('ATENÇÃO: isso apagará definitivamente todos os seus registros neste navegador. Deseja prosseguir?')&&confirmDelete('Última confirmação: apagar TUDO? Recomendamos exportar um backup antes.')){db=defaults();save();closeModal();go('home');toast('Aplicativo restaurado.');}break;}
    }
  }
  function handleSubmit(event){const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(!form.reportValidity())return;const f=new FormData(form),type=form.dataset.form,id=form.dataset.id,at=new Date().toISOString();
    const get=k=>String(f.get(k)||'').trim();
    switch(type){
    case 'subject':{const name=get('name');if(db.subjects.some(s=>s.name.toLocaleLowerCase('pt-BR')===name.toLocaleLowerCase('pt-BR')&&s.id!==id)){toast('Já existe uma disciplina com este nome.');return;}const s=sById(id);if(s){Object.assign(s,{name,color:get('color'),exam:get('exam')});}else db.subjects.push({id:uid(),name,color:get('color')||randColors[db.subjects.length%randColors.length],exam:get('exam'),createdAt:at});break;}
    case 'topic':{const date=get('studyDate'),initial=db.settings.intervals[0],newStudy=Number(get('studyMinutes'))||0;let t=tById(id);if(t){Object.assign(t,{title:get('title'),subjectId:get('subjectId'),studyDate:date,difficulty:Number(get('difficulty')),priority:Number(get('priority')),reviewMinutes:Number(get('reviewMinutes')),source:get('source'),notes:get('notes'),updatedAt:at});if(f.has('restart')){t.step=0;t.streak=0;t.intervalDay=initial;t.dueDate=addDays(date,initial);}}else{t={id:uid(),title:get('title'),subjectId:get('subjectId'),studyDate:date,difficulty:Number(get('difficulty')),priority:Number(get('priority')),reviewMinutes:Number(get('reviewMinutes')),source:get('source'),notes:get('notes'),paused:false,dueDate:addDays(date,initial),intervalDay:initial,step:0,reviewCount:0,streak:0,lapses:0,createdAt:at};db.topics.push(t);}if(newStudy>0)db.studySessions.push({id:uid(),topicId:t.id,date,minutes:newStudy,kind:'study',createdAt:at});break;}
    case 'study':{const t=tById(get('topicId'));if(!t){toast('O conteúdo selecionado não foi encontrado.');return;}db.studySessions.push({id:uid(),topicId:t.id,date:get('date'),minutes:Number(get('minutes')),kind:get('kind'),createdAt:at});if(f.has('restart')){t.step=0;t.intervalDay=db.settings.intervals[0];t.streak=0;t.dueDate=addDays(get('date'),t.intervalDay);}break;}
    case 'flash':{const existing=db.flashcards.find(x=>x.id===id);const data={topicId:get('topicId'),front:get('front'),back:get('back')};if(existing)Object.assign(existing,data);else db.flashcards.push({id:uid(),...data,step:0,intervalDay:1,streak:0,reviewCount:0,dueDate:today(),createdAt:at});break;}
    case 'question':{const existing=db.questions.find(x=>x.id===id);const data={topicId:get('topicId'),prompt:get('prompt'),options:[get('o0'),get('o1'),get('o2'),get('o3')],correct:Number(get('correct')),explanation:get('explanation')};if(existing)Object.assign(existing,data);else db.questions.push({id:uid(),...data,createdAt:at});break;}
    case 'error':{const existing=db.errors.find(x=>x.id===id);const data={topicId:get('topicId'),description:get('description'),correction:get('correction')};if(existing)Object.assign(existing,data);else db.errors.push({id:uid(),...data,at,resolved:false,source:'manual'});break;}
    case 'topic-date':{const t=tById(id);if(t)t.dueDate=get('dueDate');break;}
    case 'settings':{const intervals=get('intervals').split(/[,;\s]+/).map(Number).filter(Number.isFinite);if(!intervals.length||intervals.length>14||intervals.some((x,i)=>!Number.isInteger(x)||x<1||x>3650||(i>0&&x<=intervals[i-1]))){toast('Insira intervalos positivos, crescentes e separados por vírgulas.');return;}db.settings.intervals=intervals;db.settings.dailyCap=clamp(Number(get('dailyCap'))||40,5,600);db.settings.defaultReviewMinutes=clamp(Number(get('defaultReviewMinutes'))||12,1,180);break;}
    }
    save();closeModal();render();toast(({subject:'Disciplina salva.',topic:'Conteúdo salvo e agenda atualizada.',study:'Sessão de estudo registrada.',flash:'Flashcard salvo.',question:'Questão salva.',error:'Erro registrado.',settings:'Preferências atualizadas.','topic-date':'Data atualizada.'})[type]||'Registro salvo.');
  }
  function preserveInputRender(key,val){const elem=document.getElementById(key);const start=elem?.selectionStart;render();const replaced=document.getElementById(key);if(replaced){replaced.focus();try{replaced.setSelectionRange(start,start);}catch(e){}}}
  function handleInput(event){if(event.target?.id==='library-search'){ui.librarySearch=event.target.value;preserveInputRender('library-search',ui.librarySearch);}}
  function handleChange(event){const t=event.target;if(t.id==='library-filter'){ui.librarySubject=t.value;render();}else if(t.id==='flash-filter'){ui.flashSubject=t.value;render();}else if(t.id==='question-filter'){ui.questionSubject=t.value;render();}else if(t.id==='import-file'){importData(t.files?.[0]);}}
  window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstall=event;});
  document.addEventListener('click',event=>{if(event.target.id==='modal-backdrop'){closeModal();return;}handleClick(event).catch?.(console.error);});
  document.addEventListener('submit',handleSubmit);
  document.addEventListener('input',handleInput);
  document.addEventListener('change',handleChange);
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.getElementById('modal-root').children.length)closeModal();});
  function init(){render();if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('Service worker:',e));setTimeout(notifyIfDue,1100);setInterval(notifyIfDue,10*60*1000);}
  init();
})();
